-- Stakr LIVE schema baseline, part 1 of 2: enum types and tables.
--
-- Captured read-only from the production Neon project `cold-lab-24148964`
-- (branch `main`) on 30/10/2026, AFTER the 27/09/2026 migrations were applied.
--
-- WHY THIS EXISTS: replaying the numbered migrations into an empty database
-- yields 36 tables; production has 63. The repo could not rebuild its own
-- database. This baseline is the reproducible starting point for new
-- environments (staging, CI, local E2E, disaster recovery).
--
-- DO NOT APPLY TO AN EXISTING DATABASE. It is for empty databases only.
-- Use scripts/db-rebuild-from-baseline.sh to build one.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TYPE wallet_entry_type AS ENUM ('TOPUP', 'STAKE', 'UNSTAKE', 'WIN', 'LOSS', 'WITHDRAW_REQUEST', 'WITHDRAW_SETTLED', 'WITHDRAW_FAILED', 'FEE', 'REFUND');
CREATE TABLE ai_model_performance (id uuid NOT NULL DEFAULT gen_random_uuid(), model_version character varying(20) NOT NULL, date date NOT NULL, total_predictions integer DEFAULT 0, correct_predictions integer DEFAULT 0, false_positives integer DEFAULT 0, false_negatives integer DEFAULT 0, accuracy_rate numeric(5,2), precision_rate numeric(5,2), recall_rate numeric(5,2), f1_score numeric(5,2), average_processing_time_ms integer, max_processing_time_ms integer, min_processing_time_ms integer, layer_performance jsonb, created_at timestamp without time zone DEFAULT now());
CREATE TABLE app_data (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, app_type character varying(50) NOT NULL, data_type character varying(50) NOT NULL, value jsonb NOT NULL, "timestamp" timestamp with time zone NOT NULL, metadata jsonb, challenge_id uuid, verification_status character varying(20) DEFAULT 'pending'::character varying, verification_confidence integer, verification_reasons jsonb, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE app_integrations (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, app_type character varying(50) NOT NULL, enabled boolean DEFAULT true, auto_sync boolean DEFAULT true, privacy_level character varying(20) DEFAULT 'standard'::character varying, api_credentials jsonb, data_types jsonb, last_sync timestamp with time zone, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE audit_events (id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamp with time zone NOT NULL DEFAULT now(), actor_type character varying(20) NOT NULL, actor_id uuid, entity_type character varying(20) NOT NULL, entity_id uuid NOT NULL, action character varying(100) NOT NULL, details jsonb NOT NULL);
CREATE TABLE audit_steps (id uuid NOT NULL DEFAULT gen_random_uuid(), workflow_id uuid, step_number integer NOT NULL, step_title character varying(255) NOT NULL, content text NOT NULL, gemini_response text, rag_response text, agreement_score numeric(3,2), confidence_level character varying(20), citations jsonb, findings jsonb, processing_time_ms integer, completed_at timestamp without time zone, created_at timestamp without time zone DEFAULT now());
CREATE TABLE audit_workflows (id uuid NOT NULL DEFAULT gen_random_uuid(), project_id uuid, user_id uuid, current_step integer DEFAULT 0, total_steps integer DEFAULT 18, status character varying(50) DEFAULT 'idle'::character varying, master_report_content text, project_context jsonb, created_at timestamp without time zone DEFAULT now(), updated_at timestamp without time zone DEFAULT now(), completed_at timestamp without time zone);
CREATE TABLE ban_records (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, ban_type character varying(20) NOT NULL, ban_reason character varying(500) NOT NULL, ban_evidence jsonb, banned_by_ai boolean DEFAULT false, ai_confidence integer, banned_by_human uuid, banned_at timestamp without time zone DEFAULT now(), ban_expires_at timestamp without time zone, appeal_count integer DEFAULT 0, last_appeal_at timestamp without time zone, appeal_status character varying(20), ban_lifted_at timestamp without time zone, ban_lifted_by uuid, ban_lift_reason text, created_at timestamp without time zone DEFAULT now(), updated_at timestamp without time zone DEFAULT now());
CREATE TABLE challenge_audit_events (id uuid NOT NULL DEFAULT gen_random_uuid(), challenge_id uuid NOT NULL, actor_id uuid, event_type character varying(50) NOT NULL, reason text NOT NULL, details jsonb NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE challenge_funding (challenge_id uuid NOT NULL, user_id uuid NOT NULL, amount_cents bigint NOT NULL);
CREATE TABLE challenge_interactions (id uuid NOT NULL DEFAULT gen_random_uuid(), challenge_id uuid NOT NULL, sender_id uuid NOT NULL, target_user_id uuid NOT NULL, interaction_type character varying(50) NOT NULL, message text, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE challenge_lifecycle_queue (challenge_id uuid NOT NULL, next_attempt_at timestamp with time zone NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 0, last_error text);
CREATE TABLE challenge_participants (id uuid NOT NULL DEFAULT gen_random_uuid(), challenge_id uuid NOT NULL, user_id uuid NOT NULL, stake_amount numeric(8,2) NOT NULL, entry_fee_paid numeric(8,2) NOT NULL, insurance_purchased boolean NOT NULL DEFAULT false, insurance_fee_paid numeric(4,2) NOT NULL DEFAULT 0.00, completion_status character varying(20) NOT NULL DEFAULT 'active'::character varying, proof_submitted boolean NOT NULL DEFAULT false, verification_status character varying(20) NOT NULL DEFAULT 'pending'::character varying, reward_earned numeric(18,2) NOT NULL DEFAULT 0.00, joined_at timestamp without time zone NOT NULL DEFAULT now(), completed_at timestamp without time zone, progress integer DEFAULT 0, current_streak integer DEFAULT 0, failed_at timestamp without time zone, team_id uuid, days_remaining integer DEFAULT 0);
CREATE TABLE challenge_platform_ledger (challenge_id uuid NOT NULL, amount_cents bigint NOT NULL, reason text NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE challenge_settlement_records (challenge_id uuid NOT NULL, kind text NOT NULL, snapshot jsonb NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE challenge_teams (id uuid NOT NULL DEFAULT gen_random_uuid(), challenge_id uuid, team_name character varying(100) NOT NULL, team_color character varying(20) DEFAULT 'blue'::character varying, team_emoji character varying(10) DEFAULT '🏆'::character varying, max_members integer DEFAULT 10, current_members integer DEFAULT 0, completion_rate numeric(5,2) DEFAULT 0.00, created_at timestamp without time zone DEFAULT now());
CREATE TABLE challenges (id uuid NOT NULL DEFAULT gen_random_uuid(), title character varying(255) NOT NULL, description text NOT NULL, long_description text, category character varying(100) NOT NULL, duration character varying(50) NOT NULL, difficulty character varying(20) NOT NULL, min_stake numeric(8,2) DEFAULT 0.00, max_stake numeric(8,2) DEFAULT 0.00, host_id uuid, host_contribution numeric(8,2) NOT NULL DEFAULT 0.00, entry_fee_percentage numeric(5,2) NOT NULL DEFAULT 5.00, failed_stake_cut numeric(5,2) NOT NULL DEFAULT 20.00, start_date timestamp without time zone NOT NULL, end_date timestamp without time zone NOT NULL, status character varying(20) NOT NULL DEFAULT 'pending'::character varying, verification_type character varying(20) NOT NULL DEFAULT 'manual'::character varying, proof_requirements jsonb, rules text[], created_at timestamp without time zone NOT NULL DEFAULT now(), updated_at timestamp without time zone NOT NULL DEFAULT now(), daily_instructions text, general_instructions text, proof_instructions text, privacy_type character varying(20) DEFAULT 'public'::character varying, tags text[], thumbnail_url text, min_participants integer DEFAULT 1, max_participants integer, start_date_type character varying(20) DEFAULT 'days'::character varying, start_date_days integer DEFAULT 2, allow_points_only boolean DEFAULT false, reward_distribution character varying(30) DEFAULT 'equal-split'::character varying, selected_proof_types text[], camera_only boolean DEFAULT false, allow_late_submissions boolean DEFAULT false, late_submission_hours integer DEFAULT 4, bonus_rewards text[], invite_code character varying(20), enable_team_mode boolean DEFAULT false, team_assignment_method character varying(20) DEFAULT 'auto-balance'::character varying, number_of_teams integer DEFAULT 2, winning_criteria character varying(30) DEFAULT 'completion-rate'::character varying, losing_team_outcome character varying(20) DEFAULT 'lose-stake'::character varying, enable_referral_bonus boolean DEFAULT false, referral_bonus_percentage numeric(4,2) DEFAULT 20.00, max_referrals integer DEFAULT 3, require_timer boolean DEFAULT false, timer_min_duration integer DEFAULT 15, timer_max_duration integer DEFAULT 120, random_checkin_enabled boolean DEFAULT false, random_checkin_probability numeric(4,2) DEFAULT 30.00, moderation_status character varying(20) DEFAULT 'pending'::character varying, moderation_notes text, auto_moderated_at timestamp with time zone DEFAULT now(), ai_analysis jsonb, currency text NOT NULL DEFAULT 'CREDITS'::text, stake_tier integer, create_request_key uuid, create_request_terms jsonb, lifecycle_version integer NOT NULL DEFAULT 0, lifecycle_policy jsonb, suspended_at timestamp with time zone, resume_status character varying(20), paused_seconds numeric NOT NULL DEFAULT 0);
CREATE TABLE cheat_detection_patterns (id uuid NOT NULL DEFAULT gen_random_uuid(), pattern_name character varying(100) NOT NULL, pattern_type character varying(50) NOT NULL, pattern_description text NOT NULL, detection_rules jsonb NOT NULL, confidence_threshold integer DEFAULT 70, times_detected integer DEFAULT 0, true_positive_count integer DEFAULT 0, false_positive_count integer DEFAULT 0, effectiveness_score numeric(5,2), last_detection_at timestamp without time zone, created_by uuid, created_at timestamp without time zone DEFAULT now(), updated_at timestamp without time zone DEFAULT now(), is_active boolean DEFAULT true);
CREATE TABLE credit_grants (id uuid NOT NULL, user_id uuid NOT NULL, actor_id uuid NOT NULL, amount_cents bigint NOT NULL, reason text NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE credit_transactions (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, amount numeric(18,2) NOT NULL, transaction_type character varying(30) NOT NULL, related_challenge_id uuid, related_transaction_id uuid, description text, created_at timestamp without time zone DEFAULT now());
CREATE TABLE custom_rules (id uuid NOT NULL DEFAULT gen_random_uuid(), project_id uuid, user_id uuid, category character varying(100) NOT NULL, rule_text text NOT NULL, created_at timestamp without time zone DEFAULT now());
CREATE TABLE daily_checkins (id uuid NOT NULL DEFAULT gen_random_uuid(), participant_id uuid, challenge_id uuid, user_id uuid, checkin_date date NOT NULL, completed boolean DEFAULT false, proof_type character varying(20), proof_url text, proof_text text, points_earned integer DEFAULT 0, verified boolean DEFAULT false, verified_at timestamp without time zone, created_at timestamp without time zone DEFAULT now());
CREATE TABLE file_duplicates (id uuid NOT NULL DEFAULT gen_random_uuid(), file_hash text NOT NULL, original_file_id uuid, duplicate_file_id uuid, similarity_score numeric(4,2), detected_at timestamp without time zone DEFAULT now());
CREATE TABLE file_processing_queue (id uuid NOT NULL DEFAULT gen_random_uuid(), file_upload_id uuid, processing_type character varying(50) NOT NULL, status character varying(20) DEFAULT 'pending'::character varying, priority integer DEFAULT 0, attempts integer DEFAULT 0, max_attempts integer DEFAULT 3, error_message text, result jsonb, started_at timestamp without time zone, completed_at timestamp without time zone, created_at timestamp without time zone DEFAULT now());
CREATE TABLE file_security_incidents (id uuid NOT NULL DEFAULT gen_random_uuid(), file_upload_id uuid, user_id uuid, incident_type character varying(50) NOT NULL, severity character varying(20) NOT NULL, description text NOT NULL, evidence jsonb, status character varying(20) DEFAULT 'open'::character varying, resolved_by uuid, resolved_at timestamp without time zone, created_at timestamp without time zone DEFAULT now());
CREATE TABLE file_uploads (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, challenge_id uuid, checkin_id uuid, session_id uuid, file_key text NOT NULL, file_url text NOT NULL, original_filename text NOT NULL, sanitized_filename text NOT NULL, file_type character varying(50) NOT NULL, file_size bigint NOT NULL, file_hash text, actual_mime_type character varying(50), dimensions jsonb, risk_score integer DEFAULT 0, security_flags jsonb, validation_errors jsonb, validation_warnings jsonb, gesture_detected boolean DEFAULT false, word_detected boolean DEFAULT false, verification_confidence numeric(4,2), metadata jsonb, upload_status character varying(20) DEFAULT 'pending'::character varying, processed_at timestamp without time zone, created_at timestamp without time zone DEFAULT now(), updated_at timestamp without time zone DEFAULT now());
CREATE TABLE integration_sync_log (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, sync_type character varying(20) NOT NULL, wearable_data_points integer DEFAULT 0, app_data_points integer DEFAULT 0, verification_results integer DEFAULT 0, verified_count integer DEFAULT 0, failed_count integer DEFAULT 0, error_count integer DEFAULT 0, errors jsonb, started_at timestamp with time zone DEFAULT now(), completed_at timestamp with time zone, status character varying(20) DEFAULT 'running'::character varying, created_at timestamp with time zone DEFAULT now());
CREATE TABLE moderation_logs (id uuid NOT NULL DEFAULT gen_random_uuid(), content_hash character varying(255) NOT NULL, content_type character varying(50) NOT NULL, context character varying(100) NOT NULL, service character varying(50) NOT NULL, flagged boolean NOT NULL DEFAULT false, reasons jsonb NOT NULL DEFAULT '[]'::jsonb, confidence integer NOT NULL DEFAULT 0, action character varying(20) NOT NULL, details jsonb DEFAULT '{}'::jsonb, created_at timestamp with time zone DEFAULT now());
CREATE TABLE moderation_queue (id uuid NOT NULL DEFAULT gen_random_uuid(), content_type character varying(50) NOT NULL, content_id uuid NOT NULL, user_id uuid NOT NULL, priority integer NOT NULL DEFAULT 5, flagged_reasons jsonb NOT NULL DEFAULT '[]'::jsonb, ai_confidence integer NOT NULL DEFAULT 0, content_preview text, content_url text, status character varying(20) NOT NULL DEFAULT 'pending'::character varying, assigned_moderator_id uuid, moderator_decision character varying(20), moderator_notes text, auto_flagged_at timestamp with time zone DEFAULT now(), reviewed_at timestamp with time zone, created_at timestamp with time zone DEFAULT now());
CREATE TABLE notifications (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, type character varying(30) NOT NULL, title character varying(255) NOT NULL, message text NOT NULL, action_url text, read boolean NOT NULL DEFAULT false, metadata jsonb, created_at timestamp without time zone NOT NULL DEFAULT now());
CREATE TABLE oauth_states (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, provider character varying(50) NOT NULL, state character varying(128) NOT NULL, expires_at timestamp with time zone NOT NULL, created_at timestamp with time zone DEFAULT now());
CREATE TABLE post_comments (id uuid NOT NULL DEFAULT gen_random_uuid(), post_id uuid NOT NULL, user_id uuid NOT NULL, content text NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE post_likes (id uuid NOT NULL DEFAULT gen_random_uuid(), post_id uuid NOT NULL, user_id uuid NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE post_shares (id uuid NOT NULL DEFAULT gen_random_uuid(), post_id uuid NOT NULL, user_id uuid NOT NULL, platform character varying(50) NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE projects (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, name character varying(255) NOT NULL, location character varying(255), building_type character varying(100), wind_zone character varying(50), corrosion_zone character varying(50), earthquake_zone character varying(50), created_at timestamp without time zone DEFAULT now(), updated_at timestamp without time zone DEFAULT now());
CREATE TABLE proof_submissions (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, challenge_id uuid NOT NULL, proof_type character varying(50) NOT NULL, proof_content text NOT NULL, proof_hash character varying(64), ai_confidence integer, ai_decision character varying(20), ai_reasons jsonb, ai_layer_results jsonb, processing_time_ms integer, model_version character varying(20) DEFAULT 'v1.0'::character varying, status character varying(20) NOT NULL DEFAULT 'pending'::character varying, reviewed_by uuid, reviewed_at timestamp without time zone, human_decision character varying(20), human_notes text, appeal_submitted_at timestamp without time zone, appeal_reason text, appeal_reviewed_by uuid, appeal_reviewed_at timestamp without time zone, appeal_decision character varying(20), appeal_notes text, device_info jsonb, location_data jsonb, submission_metadata jsonb, created_at timestamp without time zone DEFAULT now(), updated_at timestamp without time zone DEFAULT now(), submission_type character varying(20) NOT NULL, admin_notes text, submitted_at timestamp without time zone DEFAULT now(), file_url text, text_content text, metadata jsonb, ai_verification_score numeric(4,2), participant_id uuid, proof_day date, submission_key uuid, superseded_at timestamp with time zone, appeal_status character varying(20), appealed_at timestamp with time zone, appeal_deadline_at timestamp with time zone);
CREATE TABLE proof_uploads (file_key text NOT NULL, storage_key text NOT NULL, user_id uuid NOT NULL, challenge_id uuid NOT NULL, content_type text NOT NULL, byte_size integer NOT NULL, confirmed_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE reports (id uuid NOT NULL DEFAULT gen_random_uuid(), workflow_id uuid, project_id uuid, user_id uuid, report_type character varying(50) NOT NULL, html_content text NOT NULL, metadata jsonb, created_at timestamp without time zone DEFAULT now());
CREATE TABLE settlements (id uuid NOT NULL DEFAULT gen_random_uuid(), challenge_id uuid NOT NULL, total_distributed numeric(10,2) NOT NULL DEFAULT 0, platform_revenue_total numeric(10,2) NOT NULL DEFAULT 0, revenue_entry_fees numeric(10,2) NOT NULL DEFAULT 0, revenue_failed_stakes_cut numeric(10,2) NOT NULL DEFAULT 0, participants_rewarded integer NOT NULL DEFAULT 0, reward_distribution_method character varying(30) NOT NULL DEFAULT 'equal-split'::character varying, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE social_comments (id uuid NOT NULL DEFAULT gen_random_uuid(), feed_item_id uuid NOT NULL, user_id uuid NOT NULL, content text NOT NULL, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE social_feed_items (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, activity_type character varying(50) NOT NULL, title text NOT NULL, description text, challenge_id uuid, metadata jsonb, is_trending boolean DEFAULT false, likes_count integer DEFAULT 0, comments_count integer DEFAULT 0, shares_count integer DEFAULT 0, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE social_feed_likes (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, feed_item_id uuid NOT NULL, created_at timestamp with time zone DEFAULT now());
CREATE TABLE social_follows (id uuid NOT NULL DEFAULT gen_random_uuid(), follower_id uuid NOT NULL, following_id uuid NOT NULL, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE transactions (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, challenge_id uuid, transaction_type character varying(30) NOT NULL, amount numeric(10,2) NOT NULL, platform_revenue numeric(10,2) NOT NULL DEFAULT 0.00, stripe_payment_id text, status character varying(20) NOT NULL DEFAULT 'pending'::character varying, created_at timestamp without time zone NOT NULL DEFAULT now());
CREATE TABLE user_achievements (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, achievement_type character varying(50) NOT NULL, title character varying(100) NOT NULL, description text NOT NULL, icon character varying(10) DEFAULT '🏆'::character varying, category character varying(30) NOT NULL, earned_at timestamp with time zone DEFAULT now(), metadata jsonb, is_hidden boolean DEFAULT false);
CREATE TABLE user_follows (id uuid NOT NULL DEFAULT gen_random_uuid(), follower_id uuid NOT NULL, following_id uuid NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE user_moderation_actions (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, action_type character varying(50) NOT NULL, reason text NOT NULL, duration_hours integer, moderator_id uuid NOT NULL, details jsonb DEFAULT '{}'::jsonb, active boolean NOT NULL DEFAULT true, expires_at timestamp with time zone, created_at timestamp with time zone DEFAULT now());
CREATE TABLE user_posts (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, content text NOT NULL, is_public boolean NOT NULL DEFAULT true, challenge_id uuid, post_type character varying(50) NOT NULL DEFAULT 'general'::character varying, include_stats boolean NOT NULL DEFAULT false, include_challenge boolean NOT NULL DEFAULT false, attached_image text, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now(), moderation_status character varying(20) DEFAULT 'pending'::character varying, moderation_notes text, auto_moderated_at timestamp with time zone DEFAULT now());
CREATE TABLE user_reports (id uuid NOT NULL DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL, reported_user_id uuid, reported_content_type character varying(50) NOT NULL, reported_content_id uuid NOT NULL, report_reason character varying(100) NOT NULL, report_details text, status character varying(20) NOT NULL DEFAULT 'pending'::character varying, moderator_id uuid, moderator_action character varying(100), moderator_notes text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE user_risk_profiles (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, risk_score integer DEFAULT 0, risk_level character varying(20) DEFAULT 'low'::character varying, total_submissions integer DEFAULT 0, approved_submissions integer DEFAULT 0, rejected_submissions integer DEFAULT 0, flagged_submissions integer DEFAULT 0, banned_submissions integer DEFAULT 0, average_submission_interval integer, submission_time_patterns jsonb, device_consistency_score integer DEFAULT 100, location_consistency_score integer DEFAULT 100, active_flags jsonb DEFAULT '[]'::jsonb, flag_history jsonb DEFAULT '[]'::jsonb, social_risk_indicators jsonb DEFAULT '{}'::jsonb, created_at timestamp without time zone DEFAULT now(), updated_at timestamp without time zone DEFAULT now(), last_analysis_at timestamp without time zone DEFAULT now());
CREATE TABLE user_social_stats (user_id uuid NOT NULL, followers_count integer DEFAULT 0, following_count integer DEFAULT 0, posts_count integer DEFAULT 0, likes_received integer DEFAULT 0, likes_given integer DEFAULT 0, social_score integer DEFAULT 0, last_active timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE user_storage_stats (user_id uuid NOT NULL, total_files integer DEFAULT 0, total_size bigint DEFAULT 0, last_upload timestamp without time zone, created_at timestamp without time zone DEFAULT now(), updated_at timestamp without time zone DEFAULT now());
CREATE TABLE users (id uuid NOT NULL DEFAULT gen_random_uuid(), email character varying(255) NOT NULL, name character varying(255) NOT NULL, avatar_url text, credits numeric(18,2) NOT NULL DEFAULT 0.00, trust_score integer NOT NULL DEFAULT 50, verification_tier character varying(20) NOT NULL DEFAULT 'manual'::character varying, challenges_completed integer NOT NULL DEFAULT 0, false_claims integer NOT NULL DEFAULT 0, current_streak integer NOT NULL DEFAULT 0, longest_streak integer NOT NULL DEFAULT 0, premium_subscription boolean NOT NULL DEFAULT false, premium_expires_at timestamp without time zone, password_hash text, created_at timestamp without time zone NOT NULL DEFAULT now(), updated_at timestamp without time zone NOT NULL DEFAULT now(), onboarding_completed boolean NOT NULL DEFAULT false, is_dev boolean NOT NULL DEFAULT false, dev_mode_enabled boolean NOT NULL DEFAULT false, dev_access_granted_by uuid, dev_access_granted_at timestamp without time zone, has_dev_access boolean NOT NULL DEFAULT false, last_login timestamp without time zone, moderation_status character varying(20) DEFAULT 'approved'::character varying, moderation_notes text, last_moderated_at timestamp with time zone, username character varying(50) NOT NULL, email_verified boolean DEFAULT false, email_verified_at timestamp without time zone, xp integer NOT NULL DEFAULT 0, level integer NOT NULL DEFAULT 1);
CREATE TABLE verification_activities (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, challenge_id uuid, file_upload_id uuid, activity_type character varying(50) NOT NULL, metadata jsonb, created_at timestamp without time zone DEFAULT now());
CREATE TABLE verification_appeals (id uuid NOT NULL DEFAULT gen_random_uuid(), verification_id uuid, user_id uuid, appeal_reason text NOT NULL, additional_evidence text, status character varying(20) DEFAULT 'pending'::character varying, admin_notes text, reviewed_by uuid, submitted_at timestamp without time zone DEFAULT now(), updated_at timestamp without time zone DEFAULT now());
CREATE TABLE verification_tokens (id uuid NOT NULL DEFAULT gen_random_uuid(), token character varying(255) NOT NULL, email character varying(255) NOT NULL, type character varying(50) NOT NULL, expires_at timestamp without time zone NOT NULL, used_at timestamp without time zone, created_at timestamp without time zone DEFAULT now(), user_id uuid);
CREATE TABLE wallet_balances (user_id uuid NOT NULL, available_cents bigint NOT NULL DEFAULT 0, staked_cents bigint NOT NULL DEFAULT 0, pending_cents bigint NOT NULL DEFAULT 0, withdrawable_cents bigint NOT NULL DEFAULT 0, updated_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE wallet_ledger (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, entry_type wallet_entry_type NOT NULL, amount_cents bigint NOT NULL, sign smallint NOT NULL, bucket text NOT NULL, ref_type text, ref_id text, idempotency_key text, created_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE wallet_topups (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, provider text NOT NULL, provider_payment_id text NOT NULL, status text NOT NULL, amount_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'USD'::text, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE wallet_withdrawals (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, status text NOT NULL, amount_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'USD'::text, wise_transfer_id text, idempotency_key text, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE wearable_data (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, device_type character varying(50) NOT NULL, data_type character varying(50) NOT NULL, value numeric NOT NULL, unit character varying(20), "timestamp" timestamp with time zone NOT NULL, metadata jsonb, challenge_id uuid, verification_status character varying(20) DEFAULT 'pending'::character varying, verification_confidence integer, verification_reasons jsonb, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE wearable_integrations (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, device_type character varying(50) NOT NULL, enabled boolean DEFAULT true, auto_sync boolean DEFAULT true, privacy_level character varying(20) DEFAULT 'standard'::character varying, api_credentials jsonb, last_sync timestamp with time zone, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE webhook_events (id text NOT NULL, type text NOT NULL, received_at timestamp with time zone NOT NULL DEFAULT now());
CREATE TABLE xp_transactions (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, amount integer NOT NULL, source character varying(50) NOT NULL, source_id uuid, description text, created_at timestamp without time zone NOT NULL DEFAULT now());
